import time
from datetime import datetime, timedelta
from functools import wraps
from inspect import signature

from robot.api.deco import keyword
from robot.libraries.BuiltIn import BuiltIn
from taf.internal.robot_typecasts import time_to_seconds
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_env_state, log_step, log_iteration

from taf.rfrl.procedures.resources.python.exceptions import TimeoutError, KeywordRetryExceededError
from taf.rfrl.procedures.resources.python.timer.exceptions import KeywordTimeoutError
from taf.rfrl.procedures.resources.python.timer.TimeMeasurement import TimeMeasurement


@log_input_and_output
def timer(multiplier=1):
    """
    Decorator which doubles function timeout but after execution check time of
     execution and raised when time will exceeded. The function must be called
     with the explicit timeout parameter

    e.g:
        func(timeout=1),
        func1(1, 2, timeout=1)

    :param multiplier: Increase maximum allowed time for achieving given condition,
                       by multiplying timeout by value of this variable.
                       Default set to 1 (original timeout will not be changed).
    :type multiplier: str or int, optional
    :raise Exception: When function is called without explicit timeout parameter
    :raise TimeoutError: When original time of execution exceeded provided timeout

    """
    def inner(func):
        time_ = TimeMeasurement()

        @wraps(func)
        def wrapper(*args, **kwargs):

            log_env_state('Method was called with those arguments Args: {}, kwargs: {}'.format(args, kwargs))
            if kwargs.get('timeout') is None:
                """
                'args_' is a list of the argument names (it may contain nested lists).
                'defaults' is an n-tuple of the default values of the last n arguments.
                """
                args_, defaults = [], {}

                sig = signature(func)
                for param_name, param in sig.parameters.items():
                    args_.append(param_name)
                    if param.default is not param.empty:
                        defaults[param_name] = param.default

                if 'timeout' not in args_:
                    raise Exception('The function must be called with the explicit timeout parameter. \n'
                                    'Input parameters of this function: {}'.format(args_))

                log_env_state('Default parameters of method. Args_: {}, defaults: {}'.format(args_, defaults))

                for key, value in defaults.items():
                    if kwargs.get(key) is None:
                        kwargs[key] = value
                log_env_state('Kwargs updated by default parameters of method: {}'.format(kwargs))

            timeout = time_to_seconds(kwargs.get('timeout') * int(multiplier))
            del kwargs['timeout']

            log_env_state('Input parameters of method. Args: {}, kwargs: {}'.format(args, kwargs))

            log_step('Executing {}'.format(func.__name__))
            time_.start_measurement_time()
            output = func(timeout=timeout * 2, *args, **kwargs)
            time_.stop_measurement_time(timeout=timeout)

            log_env_state('Output of {}: {}'.format(func.__name__, output))

            return output
        return wrapper
    return inner


@keyword(name='robot timer')
def robot_timer(name, *args):
    """
    Keyword which doubles function timeout but after execution check time of
     execution and raised when time will exceeded. The keyword must be called
     with the explicit timeout parameter

    ``name`` and ``args`` define the keyword that is executed

    e.g:

        robot timer    name=some KW    arg=arg   timeout=10

        optional:
            robot timer    name=some KW    arg=arg   multiplier=2  timeout=10

        robot timer    some KW    arg   timeout=10
    :param name: name of keyword that should be run with multiplication
    :type name: str
    :param multiplier: Increase maximum allowed time for achieving given condition,
                       by multiplying timeout by value of this variable.
                       Default set to 1 (original timeout will not be changed).
    :type multiplier: str or int, optional
    :raise Exception: When function is called without explicit timeout parameter
    :raise TimeoutError: When original time of execution exceeded provided timeout
    :return: Output of function
    """
    time_ = TimeMeasurement()
    args_ = []
    timeout_arg = None
    multiplier = 1

    for arg in _build_robot_arguments(*args):

        if 'timeout' in arg:
            timeout_arg = arg

        if 'multiplier' in arg:
            multiplier = int(arg.split('=')[1])

        else:
            if arg != timeout_arg:
                args_.append(arg)

    if timeout_arg.split("=")[0] == "timeout":
        try:
            timeout = time_to_seconds(timeout_arg.split('=')[1]) * 2 * multiplier
        except ValueError:
            timeout = time_to_seconds(BuiltIn().get_variable_value(timeout_arg.split('=')[1])) * 2 * multiplier

        args_.append('{}={}'.format(timeout_arg.split('=')[0], timeout))
    else:
        args_.append(timeout_arg)

    args_ = tuple(args_)
    log_env_state('Name: {}, original args: {}, args_: {}'.format(name, args, args_))

    try:
        timeout = timeout / 2
    except Exception:
        raise AttributeError('The function must be called with the explicit timeout parameter. \n'
                             'Input parameters of this function: {}'.format(args_))

    log_step('Executing {}'.format(name))
    time_.start_measurement_time()
    output = BuiltIn().run_keyword(name, *args_)
    time_.stop_measurement_time(timeout=timeout)

    log_env_state('Output of {}: {}'.format(name, output))

    return output


@keyword(name='wait until keyword succeeds timer')
def wait_until_keyword_succeeds_timer(retry, retry_interval, name, *args):
    """
    Keyword which doubles function timeout but after execution checks time of
     execution and raises TimeoutError when time will be exceeded.

    ``name`` and ``args`` args of the keyword are defined similarly to `Run Keyword` from Robot Framework.
    as with `Run Keyword`. How long to retry running the keyword is
    defined using ``retry`` argument either as timeout or count.
    ``retry_interval`` is the time to wait before trying to run the
    keyword again after the previous run has failed.

    If ``retry`` is given as timeout, it must be in Robot Framework's
    time format (e.g. ``1 minute``, ``2 min 3 s``, ``4.5``) that is
    explained in an appendix of Robot Framework User Guide. If it is
    given as count, it must have ``times`` or ``x`` postfix (e.g.
    ``5 times``, ``10 x``). ``retry_interval`` must always be given in
    Robot Framework's time format.

    e.g:

        wait until keyword succeeds timer  retry=1000s   retry_interval=1s  name=some KW   args=args

        optional:
             wait until keyword succeeds timer  retry=1s   retry_interval=1s  name=some KW   args=args   multiplier=2

        wait until keyword succeeds timer  1000s   1s  some KW    args
    :param retry: retry parameter as specified above
    :type retry: str
    :param retry_interval: retry interval as specified above
    :type retry_interval: str
    :param name: name of the keyword that should be run till succeeds
    :type name: str
    :param multiplier: Increase maximum allowed time for achieving given condition,
                       by multiplying timeout by value of this variable.
                       Default set to 1 (original timeout will not be changed).
    :type multiplier: str or int, optional
    :raise KeywordTimeoutError: When original time of execution exceeded provided timeout
    :raise KeywordRetryExceededError: When provided retry count is exceeded
    :return: Output of function
    """
    time_ = TimeMeasurement()
    args_ = []
    multiplier = 1

    for arg in _build_robot_arguments(*args):
        if 'multiplier' in arg:
            multiplier = int(arg.split('=')[1])
        else:
            args_.append(arg)

    args_ = tuple(args_)

    log_env_state(
        'Name: {}, retry: {}, retry_interval: {}, args: {}, new_args: {}'.format(
            name, retry, retry_interval, args, args_
        )
    )

    log_step('Executing {}'.format(name))

    if "x" not in str(retry) and "times" not in str(retry):
        retry = _adjust_timeout_to_interval(retry, retry_interval)

        log_env_state("Keyword: `{0}`, timeout for operation: {1}s, increased timeout due to delays in information "
                      "exchange: {2}s".format(name, time_to_seconds(retry) - 1, time_to_seconds(retry)))

        time_.start_measurement_time()
        output = BuiltIn().wait_until_keyword_succeeds(
            int(time_to_seconds(retry)) * 2 * multiplier, retry_interval, name, *args_)

        try:
            time_.stop_measurement_time(timeout=retry)
        except TimeoutError as e:
            raise KeywordTimeoutError("Keyword: `{0}` has exceeded provided timeout: {1}s.\n"
                                      "{2}".format(name, retry, e.message if hasattr(e, "message") else ""))

    else:
        if "x" in str(retry):
            retry = int(retry.split('x')[0])
            prefix = "x"
        elif "times" in str(retry):
            retry = int(retry.split('times')[0])
            prefix = "times"

        log_env_state("Keyword: `{0}`, retries count for operation: {1}, interval between retries "
                      ": {2}s".format(name, retry, retry_interval))
        time_.start_measurement_time()
        try:
            output = BuiltIn().wait_until_keyword_succeeds(
                "{0}{1}".format(retry * multiplier, prefix), retry_interval, name, *args_)
        except AssertionError as e:
            if hasattr(e, 'message'):
                raise KeywordRetryExceededError(e.message)

            else:
                raise KeywordRetryExceededError(e)

        time_.stop_measurement_time()

    log_env_state('Output of {}: {}'.format(name, output))

    return output


@keyword(name='poll keyword until timeout or failure')
def poll_keyword_until_timeout_or_failure(timeout, retry_interval, name, *args):
    """
    Polls a given Robot Framework keyword repeatedly until the timeout expires,
    or fails immediately if the keyword under test fails.

    ``name`` and ``args`` define the keyword that is executed.
    ``timeout`` defines how long to poll the keyword or until when to poll the keyword.
    ``retry_interval`` is the time to wait before trying to run the keyword again after the previous run has succeeded.

    :param timeout: timeout for polling the keyword
    :type timeout: str or datetime
    :param retry_interval: interval between polling attempts
    :type retry_interval: str
    :param name: name of the keyword that should be polled
    :type name: str

    e.g:
        poll keyword until timeout or failure   timeout=1000s   retry_interval=1s  name=some KW   args=args
        poll keyword until timeout or failure   1000s   1s  some KW    args
        poll keyword until timeout or failure   datetime   1s  some KW    args
    """
    builtin = BuiltIn()
    timeout = _timeout_resolver(timeout)
    interval = time_to_seconds(retry_interval)
    end_time = datetime.now() + timedelta(seconds=timeout)
    args_built = _build_robot_arguments(*args)
    log_env_state(f"Polling KW until {end_time}")
    while datetime.now() < end_time:
        builtin.run_keyword(name, *args_built)
        time.sleep(interval)


@log_input_and_output
def _build_robot_arguments(*args):
    args_ = []
    for arg in args:
        log_iteration('Building {}'.format(arg))
        if '=' in arg:
            name_arg = arg.split('=')[0]
            val = BuiltIn().get_variable_value('${' + name_arg + '}', default='builtin_default')
            if val != 'builtin_default':
                build_arg = name_arg + "=${" + name_arg + "}"
                log_iteration('Build: {}'.format(build_arg))
                args_.append(build_arg)
                continue
        if _is_it_list_or_dict_arg(arg):
            _add_list_or_dict_arg(arg, args_)
            continue
        if _is_it_list_or_dict_kwarg(arg):
            _add_list_or_dict_kwarg(arg, args_)
        else:
            build_arg = arg
            log_iteration('Build: {}'.format(build_arg))
            args_.append(build_arg)
    return args_


def _is_it_list_or_dict_arg(arg):
    return arg[0] in ["[", "{"]


def _is_it_list_or_dict_kwarg(arg):
    try:
        return arg.split('=', 1)[1][0] in ["[", "{"]
    except IndexError:
        return False


def _add_list_or_dict_kwarg(arg, args_):
    build_arg = eval(arg.split('=')[1])
    log_iteration('Build: {}'.format(build_arg))
    args_.append(build_arg)


def _add_list_or_dict_arg(arg, args_):
    build_arg = eval(arg)
    log_iteration('Build: {}'.format(build_arg))
    args_.append(build_arg)


@log_input_and_output
def _adjust_timeout_to_interval(timeout, interval):
    rest = time_to_seconds(timeout) % time_to_seconds(interval)
    if rest != 0:
        timeout = time_to_seconds(timeout) + time_to_seconds(interval) - rest
    return time_to_seconds(timeout) + 1


def _timeout_resolver(timeout):
    """Resolve timeout argument into seconds (supports duration (e.g. '5s') or datetime)."""
    if isinstance(timeout, datetime):
        delta = (timeout - datetime.now()).total_seconds()
        return max(delta, 0)

    return time_to_seconds(timeout)
